import { readdir, writeFile } from "fs/promises";
import { dirname, join } from "path";
import { fileURLToPath, pathToFileURL } from "url";
import { format, resolveConfig } from "prettier";
import { catalogueMetadata, chartMetadata } from "./dataset-registry-metadata";

const ROOT = dirname(dirname(fileURLToPath(import.meta.url)));
const DATASETS_DIR = join(ROOT, "lib", "datasets");
const CATALOGUE_DEFINITIONS_DIR = join(
	ROOT,
	"lib",
	"data",
	"catalog",
	"definitions",
);
const CATALOGUE_DEFINITIONS_INDEX = join(CATALOGUE_DEFINITIONS_DIR, "index.ts");

/**
 * Writes a generated file in the repository's own formatting. These files are
 * committed, so leaving them unformatted would fail `pnpm format:check` on the
 * next build.
 */
async function writeGenerated(path: string, source: string): Promise<void> {
	const config = await resolveConfig(path);
	await writeFile(path, await format(source, { ...config, filepath: path }));
}

const CATALOGUE_REGISTRY = join(ROOT, "lib", "data", "catalog", "registry.ts");
const CATALOGUE_TYPES = join(ROOT, "lib", "data", "catalog", "generated.ts");
const OUTPUT = join(DATASETS_DIR, "generated.ts");
const CHART_OUTPUT = join(DATASETS_DIR, "generatedCharts.tsx");

const loadModule = async (directory: string, file: string) =>
	(await import(pathToFileURL(join(directory, file)).href)) as Record<
		string,
		unknown
	>;

async function main() {
	const catalogueDefinitions = await Promise.all(
		(await readdir(CATALOGUE_DEFINITIONS_DIR))
			.filter((file) => file.endsWith(".ts") && file !== "index.ts")
			.sort()
			.map(async (file) => {
				return {
					file: file.replace(/\.ts$/, ""),
					...catalogueMetadata(
						file,
						await loadModule(CATALOGUE_DEFINITIONS_DIR, file),
					),
				};
			}),
	);
	const catalogueExports = catalogueDefinitions
		.map(({ file, name }) => `export { ${name} } from "./${file}";`)
		.join("\n");
	await writeGenerated(
		CATALOGUE_DEFINITIONS_INDEX,
		`// Generated by scripts/generate-dataset-registry.ts. Do not edit.\n${catalogueExports}\n`,
	);
	const files = (await readdir(DATASETS_DIR))
		.filter(
			(file) =>
				file.endsWith(".ts") &&
				![
					"index.ts",
					"types.ts",
					"ingestion.ts",
					"generated.ts",
					"chartGroups.ts",
				].includes(file),
		)
		.sort();
	const definitions = await Promise.all(
		files.map(async (file) => {
			const definition = chartMetadata(
				file,
				await loadModule(DATASETS_DIR, file),
			);
			const catalogue = catalogueDefinitions.find(
				(candidate) => candidate.type === definition.type,
			);
			if (!catalogue)
				throw new Error(
					`${file} has no registered catalogue definition for ${definition.type}.`,
				);
			return {
				file: file.replace(/\.ts$/, ""),
				...definition,
				chartPending: catalogue.chartPending,
			};
		}),
	);
	const catalogueImports = catalogueDefinitions
		.map(
			({ file, name }) =>
				`import { ${name} } from "./definitions/${file}";`,
		)
		.join("\n");
	const catalogueValues = catalogueDefinitions
		.map(({ name }) => `\t${name},`)
		.join("\n");
	await writeGenerated(
		CATALOGUE_REGISTRY,
		`// Generated by scripts/generate-dataset-registry.ts. Do not edit.\nimport type { DatasetDefinition } from "./types";\n${catalogueImports}\n\n/** The complete framework-neutral catalogue used by compilers and API consumers. */\nexport const CATALOGUE_DATASET_DEFINITIONS: readonly DatasetDefinition[] = [\n${catalogueValues}\n];\n`,
	);
	const catalogueTypeImports = catalogueDefinitions
		.map(
			({ file, name }) =>
				`import type { ${name} } from "./definitions/${file}";`,
		)
		.join("\n");
	const catalogueDatasetTypes = catalogueDefinitions
		.map(
			({ name }) =>
				`Awaited<ReturnType<typeof ${name}.precompile>>[string]`,
		)
		.join(" | ");
	const catalogueRecords = catalogueDefinitions
		.map(
			({ type, name }) =>
				`\t"${type}": Awaited<ReturnType<typeof ${name}.precompile>>;`,
		)
		.join("\n");
	await writeGenerated(
		CATALOGUE_TYPES,
		`// Generated by scripts/generate-dataset-registry.ts. Do not edit.\n${catalogueTypeImports}\n\nexport type CatalogueDataset = ${catalogueDatasetTypes};\nexport type CatalogueDatasetType = CatalogueDataset["type"];\nexport type CatalogueDatasetRecords = {\n${catalogueRecords}\n};\n`,
	);
	const chartDefinitions = definitions.filter(
		(definition) => !definition.chartPending,
	);
	const imports = chartDefinitions
		.map(({ file, name }) => `import { ${name} } from "./${file}";`)
		.join("\n");
	const values = chartDefinitions.map(({ name }) => `\t${name},`).join("\n");
	await writeGenerated(
		OUTPUT,
		`// Generated by scripts/generate-dataset-registry.ts. Do not edit.\nimport type { CatalogueDataset, CatalogueDatasetRecords, CatalogueDatasetType } from "../data/catalog/generated";\nimport type { ChartDatasetDefinition } from "./types";\n${imports}\n\nexport type ChartDatasetType = CatalogueDatasetType;\nexport type ChartDataset = CatalogueDataset;\nexport type ChartDatasetRecords = CatalogueDatasetRecords;\n\nexport const CHART_DATASET_DEFINITIONS: readonly ChartDatasetDefinition<ChartDataset>[] = [\n${values}\n];\n`,
	);
	const charts = chartDefinitions.flatMap(({ charts }) => charts);
	const componentPaths = [
		...new Set(charts.map((chart) => chart.componentPath)),
	];
	const componentNameForPath = new Map(
		componentPaths.map((path, index) => [path, `Chart${index}`]),
	);
	const chartImports = componentPaths
		.map((path, index) => `import Chart${index} from "${path}";`)
		.join("\n");
	const chartPresentations = componentPaths
		.map(
			(_path, index) =>
				`const Chart${index}Presentation = {\n\tcomponent: (props) => (\n\t\t<Chart${index}\n\t\t\t{...(props as ComponentProps<typeof Chart${index}>)}\n\t\t/>\n\t),\n} satisfies ChartPresentation;`,
		)
		.join("\n\n");
	const chartValues = charts
		.map((chart) => {
			const componentName = componentNameForPath.get(chart.componentPath);
			if (!componentName)
				throw new Error(`No component registered for ${chart.key}.`);
			return `\t"${chart.key}": ${componentName}Presentation,`;
		})
		.join("\n");
	await writeGenerated(
		CHART_OUTPUT,
		`"use client";\n// Generated by scripts/generate-dataset-registry.ts. Do not edit.\nimport type { ComponentProps } from "react";\nimport type { ChartPresentation, ChartPresentationRegistry } from "./types";\n${chartImports}\n\n${chartPresentations}\n\nexport const CHART_PRESENTATIONS = {\n${chartValues}\n} satisfies ChartPresentationRegistry;\n\nexport type ChartPresentationKey = keyof typeof CHART_PRESENTATIONS;\n\nexport const getChartPresentation = (\n\tkey: string,\n): ChartPresentation | undefined => CHART_PRESENTATIONS[key as ChartPresentationKey];\n`,
	);
}

main();
